INSERT INTO `product` VALUES (1,'海鮮披薩',250,1,'嚴選新鮮海鮮，搭配香濃起司與酥脆披薩餅皮，每一口都能吃到海味的鮮甜與濃郁風味，是喜愛海鮮者不可錯過的經典選擇。可能的過敏源:海鮮、乳製品','/pizza/pizza (1).jpg','',1),(2,'夏威夷披薩',250,1,'甜美鳳梨搭配香嫩火腿與濃郁起司，烘烤後散發出迷人香氣，酸甜交錯、口感層次豐富，是喜愛創意口味披薩的最佳選擇。可能的過敏源: 無。','/pizza/pizza (3).jpg','',1),(3,'雞塊',50,1,'香嫩現炸雞塊，一份七塊。可能的過敏源:無。','/fried/fried (1).jpg','',2),(4,'洋蔥圈',50,1,'洋蔥圈一份七塊，現炸新鮮。可能的過敏源:無。','/fried/fried (2).jpg','',2),(5,'伯爵鮮奶茶',80,1,'伯爵紅茶與小農鮮奶組成醇厚鮮奶茶。可能的過敏源: 牛奶、茶葉','/drink/drink (2).jpg','',3),(6,'伯爵紅茶',35,1,'選用優質紅茶葉，融合天然佛手柑香氣，茶香馥郁、口感順滑，回甘清爽，無論熱飲或冰飲都能享受典雅又迷人的伯爵風味。可能的過敏源:無。','/drink/drink (4).jpg','',3),(7,'臭臭小火鍋',190,1,'香濃獨特的臭豆腐湯底，搭配新鮮蔬菜、肉片與火鍋配料，味道鮮美、香氣十足，每一口都充滿令人難忘的經典風味，是喜愛重口味火鍋的最佳選擇。。可能的過敏源: 大豆、海鮮、豬肉、牛肉、雞肉、芝麻、麩質、花生、杏仁、奶製品','/hotpot/pot (1).jpg','',5),(8,'麻辣鴨血火鍋',210,1,'選用香麻辣湯底，搭配嫩滑鴨血、新鮮蔬菜及多款火鍋配料，湯汁濃郁、香氣撲鼻，麻辣鮮香交融，讓每一口都刺激味蕾，是喜愛重口味火鍋者的經典首選。。可能的過敏源: 大豆、花生、魚、蝦、貝類、麩質、牛奶、蛋','/hotpot/pot (4).jpg','',5),(9,'白酒蛤蠣義大利麵',180,1,'嚴選新鮮蛤蠣，以白酒、蒜香與橄欖油慢火拌炒，帶出蛤蠣自然鮮甜與淡雅酒香。搭配彈牙義大利麵條，吸附滿滿湯汁精華，清爽不膩、層次分明，是喜愛海鮮與清爽口味的經典首選。可能的過敏源:蛤蠣、麵筋、大蒜、橄欖油','/pasta/pasta (3).jpg','',9),(11,'紅酒牛肉義大利麵',150,1,'以慢火熬煮的濃郁肉醬，融合番茄的酸甜與香料風味，層次豐富、香氣十足。義大利麵條完整吸附醬汁，每一口都充滿扎實肉香，是經典不敗、老少皆宜的義式美味。可能的過敏源:無。','/pasta/pasta (6).jpg','',9),(12,'韓式燒肉披薩',240,1,'香嫩燒烤牛肉拌入韓式醬香，微甜帶鹹、層次豐富，搭配濃郁起司與酥脆披薩餅皮。鹹香中帶著韓式風味的獨特魅力，每一口都滿足又涮嘴，是喜愛創意口味的必點選擇。可能的過敏源:牛肉、乳製品、麩質','/pizza/pizza (2).jpg','',1),(13,'黑糖拿鐵',75,1,'嚴選香醇濃縮咖啡，搭配滑順鮮奶，加入慢火熬煮的黑糖糖漿，黑糖獨有的焦香與溫潤甜味，與咖啡的微苦完美融合。入口順口不膩，甜而不膏，尾韻帶有淡淡黑糖香氣，是一杯溫暖療癒、四季皆宜的經典飲品。可能的過敏源:無。','/drink/drink (6).jpg','',3);
/*!40000 ALTER TABLE `product` ENABLE KEYS */;
UNLOCK TABLES;

